pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: amount to send and an arbitrary uint to use as unlock time
    function testFuzz_property(uint256 sendAmt, uint256 unlockTime) public {
        // keep amounts reasonable and non-zero
        uint256 amt = bound(sendAmt, 1, 10 ether);
        uint256 uTime = unlockTime; // allow any unlock time (could be <= block.timestamp)

        // deploy attacker passing address of vulnerable contract c
        attacker = new Attacker(address(c));

        // fund attacker so it can call Put and re-enter
        vm.deal(address(attacker), amt);

        // attacker will call Put and during its receive will attempt to call Put again (reentrantly)
        // route the Put through attacker by calling its attack entry
        bool ok;
        try attacker.attack{value: amt}(uTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after a single external Put call from an account, the stored balance for that account equals exactly the sent value.
        // We observe c via its public getter Acc(addr).balance. attacker.addr() returns the attacker address used.
        uint stored = c.Acc(address(attacker)).balance;

        // If the reference contract prevents reentrancy correctly, stored must equal amt for ALL inputs.
        // The mutant that omits setting locked_ = true allows the attacker to reenter and may increase stored > amt for some inputs, so this assertion will fail on the mutant for some fuzz cases.
        assertTrue(stored == amt);
    }
}

// Minimal attacker that re-enters during receive by calling Put on C again
contract Attacker {
    address public target;
    bool private reentered;

    constructor(address _t) {
        target = _t;
        reentered = false;
    }

    // entry called by test: it calls Put on target; during that call, target will send control to this contract's receive (fallback)
    function attack(uint256 unlockTime) external payable {
        // forward the call to target.Put
        C(target).Put{value: msg.value}(unlockTime);
    }

    // fallback/receive will be executed during target.Put's call to Log/AddMessage or on external flows
    receive() external payable {
        // try to reenter only once to attempt to double-increment balance if reentrancy is allowed
        if (!reentered) {
            reentered = true;
            // call Put again reentrantly with zero unlock/time (or same), sending 0 value to try to trigger different observable behavior
            // send zero value reentrant Put: some contracts may still update state based on msg.value (0) but mutation at entry may differ
            // we call with 0 value to avoid needing extra balance; this still exercises reentrancy into Put
            try C(target).Put{value: 0}(0) {
            } catch {
            }
        }
    }
}

