pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz params: amount to send and an arbitrary unlockTime
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // keep amount in a reasonable range and non-zero to be admissible
        amount = bound(amount, 1 wei, 10 ether);

        // deploy an attacker that will re-enter Put during the fallback
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can send the amount
        vm.deal(address(attacker), amount);

        // record balance before
        uint before = c.Acc(address(attacker)).balance;

        // call Put from attacker which will attempt reentrancy via its fallback
        attacker.doPut{value: amount}(unlockTime);

        // after the external Put finishes, the correct contract guarantees
        // that stored balance increased exactly by msg.value (amount)
        uint after = c.Acc(address(attacker)).balance;

        // single assertion: reference preserves after - before == amount for all inputs
        assertTrue(after - before == amount);
    }
}

// Minimal re-entrant attacker: during Put's fallback (called by C when receiving ether without data)
// it immediately calls Put again on the same C contract to try to double-increment its recorded balance.
contract Attacker {
    C immutable target;
    bool reentered;
    constructor(address _t) {
        target = C(_t);
        reentered = false;
    }

    // called by test to initiate the first external Put
    function doPut(uint256 unlockTime) external payable {
        // forward a call to target.Put with this contract as msg.sender
        // the call will invoke target.fallback if sent with empty calldata in the referenced contract,
        // but Put is public so call it explicitly to trigger nonReentrant_ behavior
        target.Put{value: msg.value}(unlockTime);
    }

    // fallback will be invoked if target does a low-level call to this contract
    // or if value is sent with no data. We use it to re-enter target.Put once.
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to re-enter Put during the outer Put execution
            // send 0 value to avoid needing extra balance
            // use a small unlockTime (0) for simplicity
            target.Put{value: 0}(0);
        }
    }
}

