pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: amount to send and an arbitrary initial balance nonce to vary attacker behavior
    function testFuzz_property(uint256 sendAmt, uint256 nonce) public {
        // keep sendAmt a reasonable nonzero ether-like amount within uint128 to avoid overflow in test harness
        vm.assume(sendAmt > 0 && sendAmt <= 1 ether * 1000);

        // Deploy attacker helper that attempts to reenter c.Put during its receive
        Attacker attacker = new Attacker(address(c), nonce);

        // fund attacker so it can send
        vm.deal(address(attacker), sendAmt);

        // attacker calls Put on c, which will in its fallback/receive try to reenter Put
        // use vm.prank to make the call originate from attacker
        vm.prank(address(attacker));
        // perform the external call; call will succeed or revert depending on contract version
        bool ok;
        try c.Put{value: sendAmt}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a single external Put call by attacker, the reference contract guarantees
        // Acc[attacker].balance increased by exactly sendAmt. The mutant permitting reentrancy
        // can cause the recorded balance to be > sendAmt for some inputs.
        // Read the public getter Acc(address).balance via auto getter: c.Acc(address).balance
        (uint unlockTime, uint balance) = c.Acc(address(attacker));

        // single assertion: in the correct contract balance equals sendAmt when the Put completed successfully,
        // or equals 0 if the Put reverted (i.e., did not complete). This is a universal property the ref satisfies
        // and the mutant violates for some inputs by producing balance > sendAmt when ok==true.
        if (ok) {
            assertTrue(balance == sendAmt);
        } else {
            assertTrue(balance == 0);
        }
    }
}

