pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(address(this)); attacker = new Attacker(address(c)); }

    // fuzzed params: amount to send and a bool deciding whether attacker will reenter
    function testFuzz_property(uint128 rawAmount, bool willReenter) public {
        // keep amount in a sensible range: at least 1 wei and not absurdly large
        uint256 amount = bound(uint256(rawAmount), 1, 1 ether);

        // fund attacker and the EOA caller (address(this) will act as deployer; attacker is a contract)
        vm.deal(address(attacker), amount * 2);

        // If willReenter is false, behave as normal caller by having attacker just forward the call
        // If willReenter is true, attacker will attempt reentrancy from its receive()/fallback
        attacker.setReenter(willReenter);

        // record balance before
        uint256 before = c.Acc(address(attacker)).balance;

        // perform the Put call from attacker contract so it can optionally reenter
        vm.prank(address(attacker));
        attacker.execPut{value: amount}();

        // record after
        uint256 afterBalance = c.Acc(address(attacker)).balance;

        // The universal property: after any single external Put call, the recorded balance increases by exactly msg.value
        // i.e., afterBalance - before == amount. The correct contract enforces this for all inputs; the mutant
        // that omits locked_ = true in nonReentrant_ allows reentrant Put to increase balance by more than amount
        assertTrue(afterBalance - before == amount);
    }
}

// Minimal adversarial helper that can optionally reenter into C during its receive()
contract Attacker {
    C public target;
    bool public reenter;

    constructor(address _target) {
        target = C(_target);
        reenter = false;
    }

    function setReenter(bool r) public {
        reenter = r;
    }

    // Called by the test to perform Put via this contract so it can reenter
    function execPut() public payable {
        // call Put on target; use the helper's address as msg.sender within target
        target.Put{value: msg.value}(block.timestamp);
    }

    // If reenter flag is set, upon receiving ETH from target we attempt to call Put again
    receive() external payable {
        if (reenter) {
            // attempt to reenter Put with small value (could be zero)
            // send a small amount to reenter; ensure the attacker has funds
            uint256 v = msg.value / 2;
            if (v == 0) v = 1;
            // call Put again from this contract; if nonReentrant_ is correctly implemented this will revert
            // but we don't catch here; the call may succeed only in the buggy mutant
            target.Put{value: v}(block.timestamp);
        }
    }
}

