        // avoid zero-address caller as vm.prank with address(0) is awkward; allow many addresses
        vm.assume(caller != address(0));

        // arrange caller has funds
        vm.deal(caller, deposit + 1 ether);

        // record time and ensure wide time window; allow candidateUnlockTime be any uint
        uint256 t0 = block.timestamp;

        // perform Put as the fuzzed caller, sending deposit
        vm.prank(caller);
        c.Put{value: deposit}(candidateUnlockTime);

