pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz: actor is the caller address, amt is the value sent, unlock is the provided _unlockTime
    function testFuzz_property(address actor, uint256 amt, uint256 unlock) public {
        // Keep actor non-zero (EOA) and amt reasonably bounded so transfers are possible
        vm.assume(actor != address(0));
        // bound amt to not overflow balances in the test environment and be affordable
        amt = bound(amt, 0, 1 ether);

        // Fund the actor so they can send amt
        vm.deal(actor, amt);

        // Act as actor and call Put(unlock) sending amt
        vm.prank(actor);
        // call Put with value; note: if call reverts, the reference also would revert for bad inputs
        try c.Put{value: amt}(unlock) {
            // successful call
        } catch {
            // If it reverts, invariant about stored unlockTime doesn't apply because state didn't change;
            // we treat revert as acceptable for those inputs, so assert passes by returning early.
            return;
        }

        // The universal invariant: after Put, stored unlockTime for the caller must be >= block.timestamp
        (uint accUnlockTime, ) = getHolder(actor);
        assertTrue(accUnlockTime >= block.timestamp);
    }

    // Helper to read the public mapping struct via the public getter generated by the contract
    // The contract C has: mapping(address => Holder) public Acc; where Holder has (uint unlockTime, uint balance)
    function getHolder(address who) internal returns (uint, uint) {
        // The compiler generates a getter Acc(address) that returns (uint unlockTime, uint balance)
        return c.Acc(who);
    }
}

