pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor address and withdraw amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount in a reasonable range
        vm.assume(depositor != address(0));
        amount = bound(amount, 1 wei, 10 ether);

        // Deploy a helper that will revert on receive to model a callee that cannot accept transfer(2300)
        Reverter rev = new Reverter();

        // Fund depositor and the reverter helper so calls can be made
        vm.deal(depositor, 10 ether);
        vm.deal(address(rev), 0);

        // Make depositor put funds into c
        vm.prank(depositor);
        // call Put with unlockTime in the past so Collect check on unlockTime passes
        c.Put{value: amount}(block.timestamp - 1);

        // Ensure the deposited balance recorded in c is at least MinSum and >= amount
        // MinSum is 1 ether in contract; ensure amount >= 1 ether for admissible withdraw
        vm.assume(amount >= 1 ether);

        // Now transfer the recorded Holder entry from depositor mapping to the reverter contract by calling Collect from the reverter
        // We need the external callee to be the one receiving the funds, so we will have the depositor be msg.sender when calling Collect,
        // but we want the funds to be forwarded to msg.sender (the depositor). To simulate a failing receive at the recipient, we instead
        // perform the following: we will deploy an attacker contract Attacker that will call c.Collect and then have its receive revert.
        // But since we already have Reverter which reverts on receive, we will impersonate that Reverter as the caller who deposited funds.

        // To set up that scenario, we must have the Reverter be the depositor. So repeat deposit from Reverter and fund it.
        vm.deal(address(rev), amount);
        vm.prank(address(rev));
        // deposit from the reverter contract
        c.Put{value: amount}(block.timestamp - 1);

        // Now call Collect from the reverter: when the reference uses low-level call, it will attempt to forward all gas and the reverter's fallback will revert=false? 
        // The key difference: mutant uses transfer which will revert on a contract whose receive reverts due to limited gas; here Reverter always reverts on receive.

        bool ok;
        vm.prank(address(rev));
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: on the correct contract, Collect should NOT revert for this scenario because the original used a low-level call and handled failure by checking return value; thus ok must be true for all admissible inputs.
        // The mutant that uses transfer will cause the call to revert here for the Reverter helper and ok will be false for some inputs.
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("no receive");
    }
    receive() external payable {
        revert("no receive");
    }
}

