pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor address and deposit/withdraw amount
    function testFuzz_property(address depositor, uint256 amt, uint256 unlockDelta) public {
        // keep depositor non-zero and amt within reasonable bounds
        vm.assume(depositor != address(0));
        // bound amount to non-zero small range to avoid overflow assumptions
        amt = bound(amt, 1 wei, 5 ether);
        // unlockDelta is seconds to add to block.timestamp; allow wide range
        unlockDelta = bound(unlockDelta, 0, 1 days);

        // Deploy a helper that WILL revert on receiving ETH to simulate a reverting callee
        Reverter rev = new Reverter();

        // We will fund depositor so it can call Put
        vm.deal(depositor, amt + 1 ether);

        // depositor puts funds into contract (use fallback via direct call to Put), set unlockTime in past so Collect can run
        vm.startPrank(depositor);
        // call Put with unlock time in the past (so block.timestamp > unlockTime) or slightly future depending on fuzz
        uint256 unlockTime = block.timestamp > unlockDelta ? block.timestamp - unlockDelta : 0;
        c.Put{value: amt}(unlockTime);
        vm.stopPrank();

        // Now we transfer ownership of the stored balance to the adversarial address by directly setting Acc mapping isn't allowed
        // Instead, we simulate depositor being the adversarial contract by deploying another contract that forwards calls but has the depositor's address
        // The C contract stores balances per msg.sender; so to test difference between call vs transfer we must have the recipient be a contract that reverts on receive.
        // We'll perform Collect from the depositor account but specify that the depositor (msg.sender) is the Reverter contract by calling Collect via Reverter.

        // Transfer the depositor's accumulated balance in c to the Reverter by having depositor call a helper that calls c.Collect on behalf of the reverter
        // However Collect uses msg.sender for both lookup and payout. To have the callee be the reverter (so transfer/revert occurs to reverter), we need to call Collect from the reverter address.
        // So fund the reverter in order to be able to call c.Put from it first: deployer can fund and call Put from the reverter to create its record.

        // Make the reverter create its own account in c with sufficient balance and passed unlockTime
        vm.deal(address(rev), amt + 1 ether);
        // Have the reverter call Put to create Acc[address(rev)]
        rev.doPut{value: amt}(c, block.timestamp > 1 ? block.timestamp - 1 : 0);

        // Now try Collect from the reverter for amt. The reference contract uses low-level call and will not revert if the callee reverts (it checks _s)
        // The mutant using transfer will revert because the reverter's receive reverts. We detect whether Collect succeeded by try/catch.

        bool ok;
        try rev.doCollect(c, amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: the reference contract never reverts when the recipient revert-on-receive contract is the caller's address (it handles call failure),
        // so ok must be true for the reference for all admissible inputs. The mutant will sometimes make ok == false.
