        require(okFallback, "fallback/Put failed");

        // Now set a custom unlockTime in storage by making a direct Put with desired unlockTime
        uint256 desiredUnlock = block.timestamp + offset;
        vm.prank(actor);
        c.Put{value: 0}(desiredUnlock);

        // advance time so we can test both sides of equality; set to exactly desiredUnlock
        vm.warp(desiredUnlock);

        // try to Collect boundedCollect and record success/failure
        bool collected;
        vm.prank(actor);
        try c.Collect{value: 0}(boundedCollect) {
            collected = true;
        } catch {
            collected = false;
        }

        // General rule (reference): Collect can only succeed when block.timestamp > stored unlockTime.
        // At this point block.timestamp == desiredUnlock. Therefore reference must NOT allow Collect to succeed.
        // The mutant (>=) would allow success when equal, so will make this assertion fail for some inputs.
        assertTrue(!collected);
    }
}

